package br.com.sergio.gestaopedidos.entity;
import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.LocalDateTime;
@Entity @Table(name="estoques_insumos") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder @EqualsAndHashCode(onlyExplicitlyIncluded=true)
public class EstoqueInsumo{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@EqualsAndHashCode.Include private Long id;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="insumo_id",nullable=false,unique=true)private Insumo insumo;@Column(name="quantidade_atual",nullable=false,precision=15,scale=3)@Builder.Default private BigDecimal quantidadeAtual=BigDecimal.ZERO.setScale(3);@Column(name="custo_medio_atual",nullable=false,precision=18,scale=6)@Builder.Default private BigDecimal custoMedioAtual=BigDecimal.ZERO.setScale(6);@Column(name="valor_total_estoque",nullable=false,precision=18,scale=2)@Builder.Default private BigDecimal valorTotalEstoque=BigDecimal.ZERO.setScale(2);@Column(name="atualizado_em",nullable=false)private LocalDateTime atualizadoEm;@Version private Long versao;@PrePersist@PreUpdate void atualizar(){atualizadoEm=LocalDateTime.now();}}
